SELECT CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END AS paid_cohort, ROUND(STDDEV(amount), 2) AS stddev_amount, ROUND(AVG(amount), 2) AS avg_amount, MIN(paid_at) AS first_paid_at FROM payments WHERE order_id IN (13, 38) OR status IN ('REFUNDED', 'FAILED', 'SUCCESS') GROUP BY CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END HAVING ROUND(AVG(amount), 2) < 57 ORDER BY avg_amount DESC;
